// Serves the bundled teacher app (worker/src/public_files.js, generated by tools/bundle_public.mjs).
import { FILES } from "./public_files.js";

const bytes = {};

export function serveStatic(req, url) {
  if (req.method !== "GET" && req.method !== "HEAD") return new Response("Method not allowed", { status: 405 });
  const p = url.pathname === "/" ? "/index.html" : url.pathname;
  const f = FILES[p];
  if (!f) return new Response("Not found", { status: 404, headers: { "Content-Type": "text/plain" } });
  bytes[p] ??= Uint8Array.from(atob(f.b64), (c) => c.charCodeAt(0));
  return new Response(req.method === "HEAD" ? null : bytes[p], { headers: { "Content-Type": f.type,
    "Cache-Control": "no-cache", "X-Content-Type-Options": "nosniff" } });
}
